    "55M": "55M Degree, fixed points, dimension",
    "55N": "55N Homology and cohomology theories",
    "55P": "55P Homotopy theory",
    "55Q": "55Q Homotopy groups",
    "55R": "55R Fibre spaces and bundles",
    "57K": "57K Low-dimensional topology: surfaces and knots",
    "57M": "57M General low-dimensional topology: coverings",
    "57N": "57N Topological manifolds",
    "57Q": "57Q PL topology: triangulations",
